Function ch_to_val($ch, $first) {
    if ($ch == 'a') return $first ? 1 : -1;
    if ($ch == 'b') return $first ? -1 : 1;
    return 0;
}

Function f($sum, $mask, $first) {
    global $n, $G, $memo;
    if ($sum == 2*($n-1)) return 0;
    $key = "$sum,$mask";
    if (isset($memo[$key])) return $memo[$key];
