    // Determine reachable rows on next diagonal and their characters
    $reachable = []; // array of row => char
    for ($r = 0; $r <= $ns; $r++) {
        $c = $ns - $r;
        if ($r < 0 || $r >= $n || $c < 0 || $c >= $n) continue;
        $can_see = false;
        if ($r <= $sum && ($mask & (1 << $r))) $can_see = true;
        if ($r-1 >= 0 && ($mask & (1 << ($r-1)))) $can_see = true;
        if ($can_see) {
            $reachable[$r] = $G[$r][$c];
        }
    }
    // Group by character
    $ans = -1000000; // sufficiently small
    $processed = []; // to avoid duplicate characters
    foreach ($reachable as $r => $ch) {
        if (isset($processed[$ch])) continue;
        $processed[$ch] = true;
        // Build new mask for this character
        $new_mask = 0;
        foreach ($reachable as $rr => $ch2) {
            if ($ch2 == $ch) {
                $new_mask |= (1 << $rr);
            }
        }
        $val = ch_to_val($ch, $first) - f($ns, $new_mask, !$first);
        if ($val > $ans) $ans = $val;
    }
    $memo[$key] = $ans;
    return $ans;
}

