            G[r] = in.next().toCharArray();
        }
        int ans = ch_to_val(G[0][0],true)-f(0,new boolean[]{true},false);
        if(ans > 0) System.out.println("FIRST");
        if(ans < 0) System.out.println("SECOND");
        if(ans == 0) System.out.println("DRAW");
    }

    static int ch_to_val(char ch, boolean first) {
        if(ch=='a') return first ? 1 : -1;
        if(ch=='b') return first ? -1 : 1;
        return 0;
    }

    static long hash(int sum, boolean[] R) {
        long hash = sum;
        for(int i=0; i<R.length; i++)
            hash = hash*2 + (R[i] ? 1 : 0);
        return hash;
    }

    // Returns max score for person to play; given square has already been claimed
    static HashMap<Long,Integer> F;
    static int f(int sum, boolean[] R, boolean first) {
        long key = hash(sum, R);
        if(F.containsKey(key)) return F.get(key);
        if(sum == 2*(n-1)) return 0;

        int ans = -1000;
        int ns = sum+1;
        Character[] CH = new Character[ns+1];
        for(int r=0; r<=sum+1; r++) {
            boolean can_see = (r<R.length && R[r]) || (r-1>=0 && R[r-1]);
            if(!can_see) continue;
            int c = ns-r;
            if(c<0 || c>=n || r<0 || r>=n) continue;
            CH[r] = G[r][c];
        }

        for(int r=0; r<=sum+1; r++) {
            if(CH[r] != null) {
                char ch = CH[r];
                boolean[] NR = new boolean[ns+1];
                for(int rr=0; rr<=sum+1; rr++)
                    if(CH[rr]!=null && CH[rr] == ch) {
                        NR[rr] = true;
                        CH[rr] = null;
                    }
                ans = Math.max(ans, ch_to_val(ch,first) - f(ns, NR, !first));
            }
        }
        F.put(key, ans);
        return ans;
    }
}
